import {
    Table,
    ReferenceColumn,
    BooleanColumn,
    StringColumn,
    GuidColumn,
    DomainPathColumn,
    TranslatedFieldColumn,
    DomainIdColumn,
    TableNameColumn,
} from '../../db'

export const sys_ui_section = Table({
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        update_synch_custom: true,
    },
    display: 'caption',
    extends: 'sys_metadata',
    label: 'Form Section',
    name: 'sys_ui_section',
    schema: {
        view: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'View',
            referenceTable: 'sys_ui_view',
        }),
        title: BooleanColumn({
            label: 'Title',
        }),
        roles: StringColumn({
            array: true,
            label: 'Roles',
        }),
        sys_user: ReferenceColumn({
            cascadeRule: 'delete',
            label: 'Sys user',
            referenceTable: 'sys_user',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        sys_overrides: ReferenceColumn({
            label: [
                {
                    hint: 'Section being overridden by the current record',
                    label: 'Overrides',
                    plural: 'Overrides',
                },
            ],
            referenceTable: 'sys_ui_section',
        }),
        sys_domain_path: DomainPathColumn({
            attributes: {
                case_sensitive: true,
            },
            default: '/',
            label: 'Domain Path',
        }),
        caption: TranslatedFieldColumn({
            label: 'Caption',
        }),
        sys_domain: DomainIdColumn({
            default: 'global',
            label: [
                {
                    hint: 'Domain to which the script belongs',
                    label: 'Domain',
                    plural: 'Domains',
                },
            ],
        }),
        header: BooleanColumn({
            label: 'Header',
        }),
        name: TableNameColumn({
            label: 'Table',
            tableReference: true,
        }),
        view_name: StringColumn({
            label: 'View name',
        }),
    },
    textIndex: true,
})
